procedure CoffeeReorder {
  about "Reorder bags below their reorder point"
  policy CoffeePolicy
  sheet Beans "Beans" { blend: Text, bags: Number, reorder_at: Number, order_bags: Number, roaster: Text, price_per_bag: Money }
  trigger every day at 06:30

  let all = fetch Beans
  let low = filter all where bags <= reorder_at
  for each b in low up to 2 {
    let cost = b.order_bags * b.price_per_bag
    if cost > $120.00 {
      notify owner "Reorder of {b.blend} would cost {cost}, over the $120 limit."
      skip
    }
    order "{b.reorder_at} bags" from b.roaster cost cost, ask owner first timeout 12 hours else skip
    log "ordered {b.blend}"
  }
}
```

