procedure HardwareRefunds {
  about "Handle returns within limits, then contact the customer"
  policy HardwarePolicy
  sheet Returns "Returns" { return_no: Text, customer: Text, phone: Phone, amount: Money, bought: Date, opened: Bool, status: Text }
  trigger when new row r in Returns

  if r.opened {
    notify owner "Opened return {r.return_no} goes to the owner."
    stop "go to the owner"
  }
  if days_between(r.bought, today()) > 30 {
    notify owner "Returned {r.return_no} is older than 30 days."
    stop "older than 30 days"
  }
  if r.amount > $100.00 {
    notify owner "Returned {r.return_no} is {r.amount}, over $100. Please handle it."
    stop "over $100.00"
  }
  refund r.amount for r.return_no reason "returned item", ask owner first timeout 1 day else stop "refund not approved"
  let m = draft sms to r.phone: "Hi {r.customer default 'there'}, your return of {r.amount} has been refunded."
  let ok = request approval of m from owner timeout 1 day else stop "message not approved"
  send ok
  update r set status = "refunded"
}
```

