procedure IceRefundsOnCancel {
  about "Handle a party cancellation; refund the deposit"
  policy IcePolicy
  sheet PartyCancellations "PartyCancellations" { ref: Text, host: Text, phone: Phone, deposit: Money, party_on: Date }
  trigger when new row r in PartyCancellations

  if r.party_on < now() + 3 days {
    notify owner "Short-notice cancellation for {r.ref} would cost $100."
    stop "short notice goes to owner"
  }
  if r.deposit > $100.00 {
    notify owner "Deposit for {r.ref} is {r.deposit}, over $100. Please review."
    stop "over $100 goes to owner"
  }
  if r.deposit <= $40.00 {
    refund r.deposit for r.ref reason "short notice cancellation"
  } else {
    refund r.deposit for r.ref reason "short notice cancellation", ask owner first timeout 1 day else stop "refund not approved"
  }
  let m = draft sms to r.phone: "Hi {r.host default 'there'}, your deposit of {r.deposit} is coming back."
  let ok = request approval of m from owner timeout 1 day else stop "message not approved"
  send ok
}
