  sheet Consignments "Consignments" { consignor: Text, phone: Phone, item: Text, listed_on: Date, price: Money, sold: Bool, status: Text, bank_note: Text private }
  trigger every day at 18:00

  let all = fetch Consignments
  let these = filter all where sold == true
  for each r in these up to 30 {
    let pay = round(r.price * 0.60)
    refund r.price for r.id reason "broker payment", ask owner first timeout 12 hours else skip
    order "{pay}" from r.consignor cost pay, ask owner first timeout 12 hours else skip
    update r set status = "paid-out"
  }
}

