procedure VetLateBalance {
  about "Remind late pet owners; escalate very late ones"
  policy VetPolicy
  sheet Pets "Pets" { owner: Text, phone: Phone, vaccine_due: Date, status: Text, balance: Money, medical_notes: Text private }
  trigger every day at 18:00

  let all = fetch Pets
  let late = filter all where balance > $0.00 and days_between(vaccine_due, today()) > 5
  for each r in late up to 40 {
    if days_between(r.vaccine_due, today()) > 14 {
      notify owner "{r.owner} is very late ({r.balance}). Please call."
    } else {
      let m = draft sms to r.phone: "Hello {r.owner}, our records show a balance of {r.balance}. Questions? Just reply."
      let ok = request approval of m from owner timeout 12 hours else skip
      send ok
    }
  }
}
